/* eslint-disable @next/next/no-img-element -- variants are pre-generated by sharp; see DESIGN/CLAUDE.md */
import { cn } from "@/lib/cn";
import { mediaUrl, type MediaAsset } from "@/lib/media/types";

type MediaImageProps = {
  media: MediaAsset;
  /** Responsive `sizes` attribute, e.g. "(min-width: 1024px) 50vw, 100vw". */
  sizes: string;
  /** Above-the-fold image: eager load + high fetch priority. */
  priority?: boolean;
  className?: string;
  /** Override media alt (e.g. decorative images → ""). */
  alt?: string;
};

/** Renders a library image with srcset from its WebP variants and a blur placeholder. */
export function MediaImage({ media, sizes, priority, className, alt }: MediaImageProps) {
  const variants = media.variants.length
    ? media.variants
    : [{ width: media.width, height: media.height, path: "", size: 0 }];
  const largest = variants[variants.length - 1];

  return (
    <img
      src={mediaUrl(largest.path)}
      srcSet={variants.map((v) => `${mediaUrl(v.path)} ${v.width}w`).join(", ")}
      sizes={sizes}
      width={media.width}
      height={media.height}
      alt={alt ?? media.alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding={priority ? "sync" : "async"}
      className={cn("bg-ink/8 bg-cover bg-center", className)}
      style={media.blurDataUrl ? { backgroundImage: `url(${media.blurDataUrl})` } : undefined}
    />
  );
}
